        // 只有3个字段，用完了就丢，不保存到成员变量
    }
};
return tpl.query(sql, m);
```

### ③ `PreparedStatement` — 写操作

所有 INSERT/UPDATE/DELETE 都用传统 JDBC 方式，因为需要接收 Service 传入的 `Connection`：

```java
public int save(Connection conn, Contact x) throws SQLException {
    String sql = "INSERT INTO crm_contact(...) VALUES(?,?,...,1)";
    try (PreparedStatement p = conn.prepareStatement(sql)) {
        bind(p, x);           // 绑定参数
        return p.executeUpdate();  // 返回影响行数
    }
    // try-with-resources 自动关闭 PreparedStatement
}
```

### ④ `try-with-resources` — 自动关闭资源

```java
// DAO 的写方法都用这个语法
try (PreparedStatement p = conn.prepareStatement(sql)) {
    // 不管正常结束还是抛异常，p 都会自动 close()
}
// 等价于手动写 finally { p.close(); }
```

### ⑤ `Statement.RETURN_GENERATED_KEYS` — 取回自增主键

```java
try (PreparedStatement p = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
    p.executeUpdate();
    try (ResultSet r = p.getGeneratedKeys()) {
        r.next();
        return r.getInt(1);  // 拿到刚才 INSERT 自动生成的 id
    }
}
```

### ⑥ `EmptyResultDataAccessException` — 查不到时的处理

```java
public Contact findById(int id, ...) {
    try {
        return tpl.queryForObject(sql, mapper, id);
    } catch (EmptyResultDataAccessException e) {
        return null;  // 查不到返回 null，不抛异常到页面
    }
}
```

